Language: C (imperative paradigm)

## Task specification given to the author
Implement two approximation algorithms for the metric Travelling Salesman Problem
(MST double tree and Christofides) in C using the header file tsp_approx.h.

Input: an array `pts` of `n` points (`TspPoint {int x; int y;}`), 0 <= n <= 40,
|coordinate| < 10^4. When n == 0, `pts` may be NULL. Vertex i is pts[i] (0-based,
input order). Points may coincide (distance 0). The input is never modified.
Distance is Manhattan: d(p, q) = |p.x - q.x| + |p.y - q.y| (an integer metric).

Tour: a TourResult whose `tour` is a permutation of all vertex indices 0..n-1
starting with vertex 0, `n` is its length, and `cost` is the closed-tour cost
  d(tour[0], tour[1]) + ... + d(tour[n-2], tour[n-1]) + d(tour[n-1], tour[0]).
For n == 1 the tour is [0] with cost 0; for n == 2 the cost is 2 * d(0, 1).

The MST (unique by these rules) - Prim's algorithm starting from vertex 0:
  repeat n-1 times: among the non-tree vertices v choose the one with the smallest
  key(v) = min over tree vertices u of d(u, v); ties -> the smallest index v.
  Its parent is the tree vertex u with d(u, v) == key(v); ties -> the SMALLEST
  index u (not the first one found, not the most recently added one).
  Add v to the tree with the edge (parent, v).

- Implement `tsp_mst_weight`: Return the sum of the weights of that MST's edges.
  Return 0 for n <= 1.

- Implement `tsp_double_tree`: Return the preorder (DFS) sequence of that MST
  rooted at vertex 0, visiting the children of every vertex in ASCENDING index
  order, together with its closed-tour cost. The answer is unique and compared
  exactly. Return NULL for n == 0; for n == 1 return tour [0], cost 0.

- Implement `tsp_matching_weight`: Let O be the set of vertices with odd degree in
  that MST (|O| is even). Return the MINIMUM total weight (distance d) of a perfect
  matching of O (pairs of distinct vertices of O, every vertex of O in exactly one
  pair). It must be exact - greedy nearest-pair matching is wrong. |O| <= 16 in all
  tests, so an exact bitmask DP over subsets is fine (blossom not required).
  Return 0 for n <= 1.

- Implement `tsp_christofides`: Build the multigraph consisting of the MST edges
  plus the edges of a minimum-weight perfect matching of O. If an edge is both an
  MST edge and a matching edge it is a DOUBLE edge - keep both copies (parallel
  edges). Find an Eulerian circuit of this multigraph starting at vertex 0
  (Hierholzer), then shortcut it: keep only the first occurrence of every vertex.
  The resulting tour starts with 0. Its cost never exceeds
  tsp_mst_weight + tsp_matching_weight. Any minimum matching and any Eulerian
  circuit are accepted. Return NULL for n == 0; for n == 1 return tour [0], cost 0.

- Implement `free_tour_result`: Free the result and its `tour` array.
  `free_tour_result(NULL)` is a no-op.

Ownership: every returned TourResult and its `tour` array are fresh heap
allocations owned by the caller (released with `free_tour_result`).

Constraints:
  - No memory leaks (verified by valgrind); free every temporary allocation.
  - All functions must handle their edge cases (n == 0, 1, 2, coinciding points)
    without crashing.

## Contract given to the author (tsp_approx.h, not written by the author)
```c
#ifndef TSP_APPROX_H
#define TSP_APPROX_H

/*
 * Metric TSP approximation on points with Manhattan distance
 * d(p, q) = |p.x - q.x| + |p.y - q.y|.
 * Vertices are the indices 0..n-1 of pts in input order. Points may coincide.
 */

typedef struct {
    int x;
    int y;
} TspPoint;

typedef struct {
    int* tour;   /* length n; permutation of 0..n-1 starting with 0; heap */
    int n;
    int cost;    /* closed-tour cost, including the edge back to tour[0] */
} TourResult;

/* Total weight of the MST built by the tie-broken Prim's algorithm; 0 if n <= 1. */
int tsp_mst_weight(const TspPoint* pts, int n);

/* Preorder walk of that MST (root 0, children in ascending index order).
   NULL if n == 0. Caller frees with free_tour_result. */
TourResult* tsp_double_tree(const TspPoint* pts, int n);

/* Minimum-weight perfect matching on the odd-degree vertices of that MST; 0 if n <= 1. */
int tsp_matching_weight(const TspPoint* pts, int n);

/* Christofides tour (MST + min matching, Eulerian circuit from 0, shortcut).
   NULL if n == 0. Caller frees with free_tour_result. */
TourResult* tsp_christofides(const TspPoint* pts, int n);

/* Frees the result and its tour array. Accepts NULL. */
void free_tour_result(TourResult* result);

#endif

```

## Code to evaluate (tsp_approx.c)
```c
#include <stdlib.h>
#include <limits.h>
#include "tsp_approx.h"

static int dist_pt(const TspPoint* a, const TspPoint* b) {
    int dx = a->x - b->x;
    int dy = a->y - b->y;
    if (dx < 0) dx = -dx;
    if (dy < 0) dy = -dy;
    return dx + dy;
}

/* Tie-broken Prim's algorithm from vertex 0. Fills parent[] (parent[0] = -1).
   Requires n >= 1 and parent allocated with n entries. Returns total weight. */
static int build_mst(const TspPoint* pts, int n, int* parent) {
    int total = 0;
    parent[0] = -1;
    if (n <= 1) return 0;

    char* in = (char*)calloc((size_t)n, 1);
    int* key = (int*)malloc((size_t)n * sizeof(int));
    in[0] = 1;
    for (int v = 1; v < n; v++) {
        key[v] = dist_pt(&pts[0], &pts[v]);
        parent[v] = 0;
    }

    for (int step = 1; step < n; step++) {
        int best = -1;
        for (int v = 0; v < n; v++) {
            if (!in[v] && (best < 0 || key[v] < key[best])) best = v;
        }
        in[best] = 1;
        total += key[best];
        for (int v = 0; v < n; v++) {
            if (in[v]) continue;
            int d = dist_pt(&pts[best], &pts[v]);
            if (d < key[v] || (d == key[v] && best < parent[v])) {
                key[v] = d;
                parent[v] = best;
            }
        }
    }

    free(in);
    free(key);
    return total;
}

static int tour_cost(const TspPoint* pts, const int* tour, int n) {
    if (n <= 1) return 0;
    int c = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1 == n) ? 0 : i + 1;
        c += dist_pt(&pts[tour[i]], &pts[tour[j]]);
    }
    return c;
}

static TourResult* make_result(int n) {
    TourResult* r = (TourResult*)malloc(sizeof(TourResult));
    if (!r) return NULL;
    r->tour = (int*)malloc((size_t)(n > 0 ? n : 1) * sizeof(int));
    r->n = n;
    r->cost = 0;
    return r;
}

static void preorder(int u, const int* parent, int n, int* out, int* cnt) {
    out[(*cnt)++] = u;
    for (int v = 1; v < n; v++) {
        if (parent[v] == u) preorder(v, parent, n, out, cnt);
    }
}

/* Exact minimum perfect matching on k points (k even, k <= ~20) via bitmask DP.
   If outA/outB are non-NULL, the matched pairs (as vertex indices) are stored. */
static int min_matching(const TspPoint* pts, const int* O, int k,
                        int* outA, int* outB) {
    if (k == 0) return 0;
    int full = 1 << k;
    int* dp = (int*)malloc((size_t)full * sizeof(int));
    const int INF = INT_MAX / 2;
    dp[0] = 0;
    for (int mask = 1; mask < full; mask++) {
        int i = 0;
        while (!((mask >> i) & 1)) i++;
        int best = INF;
        for (int j = i + 1; j < k; j++) {
            if (!((mask >> j) & 1)) continue;
            int sub = mask ^ (1 << i) ^ (1 << j);
            if (dp[sub] >= INF) continue;
            int c = dp[sub] + dist_pt(&pts[O[i]], &pts[O[j]]);
            if (c < best) best = c;
        }
        dp[mask] = best;
    }

    int result = dp[full - 1];

    if (outA && outB) {
        int mask = full - 1;
        int np = 0;
        while (mask) {
            int i = 0;
            while (!((mask >> i) & 1)) i++;
            int found = 0;
            for (int j = i + 1; j < k && !found; j++) {
                if (!((mask >> j) & 1)) continue;
                int sub = mask ^ (1 << i) ^ (1 << j);
                if (dp[sub] >= INF) continue;
                if (dp[sub] + dist_pt(&pts[O[i]], &pts[O[j]]) == dp[mask]) {
                    outA[np] = O[i];
                    outB[np] = O[j];
                    np++;
                    mask = sub;
                    found = 1;
                }
            }
            if (!found) break; /* should not happen */
        }
    }

    free(dp);
    return result;
}

/* Collects odd-degree vertices of the tree given by parent[]. Returns count k. */
static int odd_vertices(const int* parent, int n, int* O) {
    int* deg = (int*)calloc((size_t)n, sizeof(int));
    for (int v = 1; v < n; v++) {
        deg[v]++;
        deg[parent[v]]++;
    }
    int k = 0;
    for (int v = 0; v < n; v++) {
        if (deg[v] & 1) O[k++] = v;
    }
    free(deg);
    return k;
}

int tsp_mst_weight(const TspPoint* pts, int n) {
    if (n <= 1) return 0;
    int* parent = (int*)malloc((size_t)n * sizeof(int));
    int w = build_mst(pts, n, parent);
    free(parent);
    return w;
}

TourResult* tsp_double_tree(const TspPoint* pts, int n) {
    if (n == 0) return NULL;
    TourResult* r = make_result(n);
    if (!r) return NULL;
    if (n == 1) {
        r->tour[0] = 0;
        r->cost = 0;
        return r;
    }
    int* parent = (int*)malloc((size_t)n * sizeof(int));
    build_mst(pts, n, parent);
    int cnt = 0;
    preorder(0, parent, n, r->tour, &cnt);
    r->cost = tour_cost(pts, r->tour, n);
    free(parent);
    return r;
}

int tsp_matching_weight(const TspPoint* pts, int n) {
    if (n <= 1) return 0;
    int* parent = (int*)malloc((size_t)n * sizeof(int));
    build_mst(pts, n, parent);
    int* O = (int*)malloc((size_t)n * sizeof(int));
    int k = odd_vertices(parent, n, O);
    int w = min_matching(pts, O, k, NULL, NULL);
    free(O);
    free(parent);
    return w;
}

TourResult* tsp_christofides(const TspPoint* pts, int n) {
    if (n == 0) return NULL;
    TourResult* r = make_result(n);
    if (!r) return NULL;
    if (n == 1) {
        r->tour[0] = 0;
        r->cost = 0;
        return r;
    }

    int* parent = (int*)malloc((size_t)n * sizeof(int));
    build_mst(pts, n, parent);

    int* O = (int*)malloc((size_t)n * sizeof(int));
    int k = odd_vertices(parent, n, O);
    int np = k / 2;
    int* pairA = (int*)malloc((size_t)(np > 0 ? np : 1) * sizeof(int));
    int* pairB = (int*)malloc((size_t)(np > 0 ? np : 1) * sizeof(int));
    min_matching(pts, O, k, pairA, pairB);

    int E = (n - 1) + np;
    int* eu = (int*)malloc((size_t)E * sizeof(int));
    int* ev = (int*)malloc((size_t)E * sizeof(int));
    for (int v = 1; v < n; v++) {
        eu[v - 1] = v;
        ev[v - 1] = parent[v];
    }
    for (int p = 0; p < np; p++) {
        eu[n - 1 + p] = pairA[p];
        ev[n - 1 + p] = pairB[p];
    }

    /* Multigraph adjacency in CSR form. */
    int* deg2 = (int*)calloc((size_t)n, sizeof(int));
    for (int e = 0; e < E; e++) {
        deg2[eu[e]]++;
        deg2[ev[e]]++;
    }
    int* start = (int*)malloc((size_t)(n + 1) * sizeof(int));
    start[0] = 0;
    for (int v = 0; v < n; v++) start[v + 1] = start[v] + deg2[v];
    int* fill = (int*)calloc((size_t)n, sizeof(int));
    int* adj = (int*)malloc((size_t)(2 * E) * sizeof(int));
    for (int e = 0; e < E; e++) {
        adj[start[eu[e]] + fill[eu[e]]++] = e;
        adj[start[ev[e]] + fill[ev[e]]++] = e;
    }

    /* Hierholzer's algorithm starting at vertex 0. */
    char* used = (char*)calloc((size_t)E, 1);
    int* ptr = (int*)calloc((size_t)n, sizeof(int));
    int* stack = (int*)malloc((size_t)(E + 2) * sizeof(int));
    int* circuit = (int*)malloc((size_t)(E + 2) * sizeof(int));
    int sp = 0, cn = 0;
    stack[sp++] = 0;
    while (sp > 0) {
        int v = stack[sp - 1];
        while (ptr[v] < deg2[v] && used[adj[start[v] + ptr[v]]]) ptr[v]++;
        if (ptr[v] < deg2[v]) {
            int e = adj[start[v] + ptr[v]];
            used[e] = 1;
            int w = (eu[e] == v) ? ev[e] : eu[e];
            stack[sp++] = w;
        } else {
            circuit[cn++] = v;
            sp--;
        }
    }

    /* Shortcut: keep first occurrence of each vertex. */
    char* visited = (char*)calloc((size_t)n, 1);
    int cnt = 0;
    for (int i = 0; i < cn && cnt < n; i++) {
        int v = circuit[i];
        if (!visited[v]) {
            visited[v] = 1;
            r->tour[cnt++] = v;
        }
    }
    /* Ensure the tour starts with 0 (it does by construction). */
    r->cost = tour_cost(pts, r->tour, n);

    free(visited);
    free(circuit);
    free(stack);
    free(ptr);
    free(used);
    free(adj);
    free(fill);
    free(start);
    free(deg2);
    free(ev);
    free(eu);
    free(pairB);
    free(pairA);
    free(O);
    free(parent);
    return r;
}

void free_tour_result(TourResult* result) {
    if (!result) return;
    free(result->tour);
    free(result);
}

```
